(function(root){'use strict';
root.createCashUI=function(host){
 const {state,save,render,openModal,toast,cards,safe,bb}=host,C=root.MesaCash,D=root.MesaCashCoach,E=root.MesaEngine;
 let timer=null,paused=false,lastEvent='',ai={status:'idle'},studyRows=[],studyIndex=0,studyAnswer=null,studyScore=0;
 state.cash ||= C.make();state.cashArchives ||= [];state.prefs.cashSpeed ||= 'normal';
 const t=()=>state.cash,amount=n=>bb(C.bb(n)),pct=n=>n===null?'—':Math.round(n*100)+'%',labels={fold:'Desistir',call:'Pagar',check:'Check',raise:'Apostar / aumentar'};
 const speeds={slow:1100,normal:620,fast:230,off:0};
 const reduced=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const duration=()=>reduced()?0:speeds[state.prefs.cashSpeed]??620;
 const a=(action,label,cls='outline-btn',extra='')=>`<button class="${cls}" data-do="cash-${action}" ${extra}>${label}</button>`;
 function current(){if(!t().hand&&t().players[0].stack>=100)C.start(t());return t().hand;}
 function schedule(view){clearTimeout(timer);if(view!=='train'||paused)return;const h=current();if(h.phase==='finished'||(h.phase==='betting'&&h.actor===0))return;timer=setTimeout(()=>{if(document.hidden||document.getElementById('modal').open){schedule(view);return;}C.step(t());save();render();},Math.max(30,duration()*(h.phase==='dealing'?.28:1)));}
 const xy=[['50%','80%'],['12%','68%'],['12%','27%'],['50%','12%'],['88%','27%'],['88%','68%']],front=[['50%','65%'],['27%','65%'],['27%','33%'],['50%','26%'],['73%','33%'],['73%','65%']];
 function flight(event,animate){if(!animate||!duration())return '';const fx=(seat,from,to,n,kind='')=>`<span class="cash-flight ${kind}" aria-hidden="true" style="--sx:${from[0]};--sy:${from[1]};--tx:${to[0]};--ty:${to[1]};--flight:${duration()}ms"><i class="chip mint"></i><b>${amount(n)}</b></span>`;
 if(['raise','call','blind'].includes(event.type))return fx(event.seat,xy[event.seat],front[event.seat],event.amount);
 if(event.type==='ante')return fx(event.seat,xy[event.seat],['50%','39%'],event.amount);
 if(event.type==='collect')return event.amounts.map((n,i)=>n?fx(i,front[i],['50%','39%'],n):'').join('');
 if(['award','refund'].includes(event.type))return fx(event.seat,['50%','39%'],xy[event.seat],event.amount,'winning');
 if(event.type==='button'){const from=xy[(t().dealer+5)%6],to=xy[t().dealer];return `<span class="cash-flight button-flight" aria-hidden="true" style="--sx:${from[0]};--sy:${from[1]};--tx:${to[0]};--ty:${to[1]};--flight:${duration()}ms">D</span>`;}return '';}
 function eventText(e){if(!e)return 'Preparando a mesa';const name=e.seat===null?'':t().players[e.seat].name;const text={button:'está no botão',ante:`pagou o ante: ${amount(e.amount)} BB`,blind:`postou ${amount(e.amount)} BB`,fold:'desistiu',check:'deu check',call:`pagou ${amount(e.amount)} BB`,raise:`${(e.previousBet??(e.to===e.amount?0:1))===0?'apostou':'aumentou para'} ${amount(e.to)} BB${e.allIn?' · all-in':''}`,collect:'Apostas recolhidas ao pote',reveal:`${E.STREETS[e.street]} revelado`,deal:'recebeu uma carta',showdown:'Comparando as mãos',award:`recebeu ${amount(e.amount)} BB`,refund:`recebeu ${amount(e.amount)} BB de volta`,finished:'Mão encerrada'};return ['collect','reveal','showdown','finished'].includes(e.type)?text[e.type]:name+' '+(text[e.type]||'agiu');}
 function bankroll(){const table=t(),stack=table.players[0].stack,total=table.reserve+stack,net=total-table.initialBankroll;return `<div class="cash-bank"><div><small>Na mesa</small><strong>${amount(stack)} <em>BB</em></strong></div><div><small>Reserva simulada</small><strong>${amount(table.reserve)} <em>BB</em></strong></div><div class="${net<0?'negative':'positive'}"><small>Resultado acumulado</small><strong>${net>0?'+':''}${amount(net)} <em>BB</em></strong></div><span class="bank-total">Banca total: ${amount(total)} BB · fichas fictícias</span></div>`;}
 function calibration(){const n=t().history.length,r=D.summarize(t());return `<section class="session-card calibration-card"><div class="session-heading"><h2>${n<10?'Conhecendo seu jogo':'Calibração contínua'}</h2><span>${n<10?n+'/10 mãos':n+' mãos observadas'}</span></div><div class="calibration-track"><span style="width:${Math.min(100,n*10)}%"></span></div><p>${n<10?'Jogue no seu ritmo. A primeira leitura aparece após dez mãos.':'Seu perfil é atualizado a cada mão. As modalidades são avaliadas separadamente.'}</p>${n>=10?a('report','Ver meu diagnóstico ↗','text-button'):''}<div class="cash-mini-stats"><span>${r.unassisted} decisões sem ajuda</span><span>10ª mão: Omaha 4</span></div></section>`;}
 function controls(){const h=current(),v=C.visible(t());if(h.phase==='finished'){
 const net=h.delta,win=h.payouts.filter(p=>p.type==='award'),winners=[...new Set(win.map(p=>p.seat))];return `<section class="decision-card cash-result"><div class="feedback-mark ${net>=0?'':'wrong'}">${net>=0?'✓':'↗'}</div><span class="eyebrow">Mão ${h.number} encerrada</span><h2>${net>0?'Pote recebido.':net===0?'Saldo preservado.':'Uma mão para revisar.'}</h2><div class="hand-net ${net<0?'negative':'positive'}">${net>0?'+':''}${amount(net)} <small>BB nesta mão</small></div><p>${winners.map(i=>safe(t().players[i].name)).join(', ')} ${winners.length>1?'dividiram os potes.':'recebeu o pote.'} A qualidade da decisão é avaliada separadamente do resultado.</p>${h.showdown?`<div class="cash-showdown-list">${Object.entries(h.evaluated||{}).map(([i,e])=>`<div><b>${safe(t().players[i].name)} · ${safe(e.name)}</b>${cards([...e.holeUsed,...e.boardUsed],'small')}<small>${e.holeUsed.length} própria(s) + ${e.boardUsed.length} da mesa</small></div>`).join('')}</div>`:''}${a('review','Revisar decisões desta mão','outline-btn')}${t().players[0].stack<100?`<p class="method-note">Saldo abaixo de 1 BB. A reentrada usa sua reserva simulada.</p>${a('rebuy',t().reserve>=100?'Reentrar com até 100 BB':'Reserva esgotada','next-button',t().reserve<100?'disabled':'')}`:a('next',t().history.length===10?'Abrir diagnóstico e continuar →':'Próxima mão →','next-button')}<p class="sample-note">O botão avança quando você inicia a próxima mão.</p></section>`;}
 if(!v.legal)return `<section class="decision-card waiting-card"><span class="eyebrow">${h.phase==='betting'?'Vez de '+safe(t().players[h.actor]?.name||'mesa'):h.phase==='dealing'?'Distribuição':h.phase==='settle'?'Resultado':'A mesa está em movimento'}</span><h2>${paused?'Mesa pausada.':'Observe a ação.'}</h2><p class="event-live" role="status">${safe(eventText(h.event))}</p>${a('skip','Pular animações até minha vez →','next-button')}${a('pause',paused?'▶ Retomar':'Ⅱ Pausar','text-button')}</section>`;
 const l=v.legal,s=C.publicSpot(t()),min=amount(l.minTo),max=amount(l.maxTo),initial=amount(Math.min(l.maxTo,Math.max(l.minTo,h.street?Math.round((C.pot(t())+l.call)*.5)+l.call+l.already:250)));
 return `<section class="decision-card cash-decision" id="cash-decision"><div class="decision-top"><span class="eyebrow">Sua vez · ${E.STREETS[h.street]}</span><span class="position-badge">${C.position(t())}</span></div><h2>${l.call?'Como você responde?':'Qual é a sua jogada?'}</h2><p>${l.call?`Pagar custa ${amount(l.call)} BB. O pote, com as apostas na mesa, tem ${bb(v.pot)} BB.`:'Você pode dar check sem pagar ou abrir uma aposta.'}</p><div class="cash-context"><span>${h.kind==='omaha'?'PLO · limite do pote':'Hold’em · no-limit'}</span><span>${s.opponents} adversário(s) ativo(s)</span></div><div class="actions cash-basic">${a('play','× <b>Desistir</b><span>Encerrar sua participação</span>','action','data-value="fold"')}${a('play',l.call?`= <b>Pagar</b><span>${amount(l.call)} BB${l.call===l.stack?' · all-in':''}</span>`:'− <b>Check</b><span>Passar sem pagar</span>','action',`data-value="${l.call?'call':'check'}"`)}</div>${l.raise?`<div class="raise-control"><label for="cash-raise">${h.currentBet?'Aumentar para':'Apostar'} <span>Total nesta rodada · BB</span></label><div class="raise-entry"><input id="cash-raise" type="number" min="${C.bb(l.minTo)}" max="${C.bb(l.maxTo)}" step="0.01" value="${Number(initial.replace(/\./g,'').replace(',','.'))}" inputmode="decimal"><button data-do="cash-play" data-value="raise" class="next-button">${h.currentBet?'Aumentar':'Apostar'} ↗</button></div><div class="sizing-buttons">${[.33,.5,.75,1].map(f=>a('size',Math.round(f*100)+'% pote','size-button',`data-fraction="${f}"`)).join('')}${l.allIn?a('size','All-in','size-button','data-fraction="all"'):''}</div><small>De ${min} a ${max} BB${h.kind==='omaha'?' · limite PLO':''}. ${l.minTo<l.fullMinTo?'All-in curto: não reabre aumento para quem já agiu.':''}</small></div>`:''}${a('hint','ⓘ Consultar referência (marca ajuda)','text-button')}<p class="model-tag">${t().history.length<10?'Avaliação inicial · feedback ao encerrar a mão':'Treino contínuo · confira o raciocínio após a mão'}</p></section>`;}
 function table(){const h=current(),v=C.visible(t()),key=h.id+':'+h.event?.id,animate=key!==lastEvent;lastEvent=key;
 const atmosphere=E.ATMOSPHERES[t().config.atmosphere],backs=n=>`<div class="seat-cards">${Array.from({length:n},()=>'<span class="card-back"></span>').join('')}</div>`;
 const seats=v.players.slice(1).map(p=>`<div class="seat pos-${p.seat} ${p.folded?'folded':''} ${h.actor===p.seat?'active-player attacking':''}"><span class="seat-avatar" aria-hidden="true">${safe(p.name[0])}</span>${p.cards?cards(p.cards,'small'):backs(p.dealt)}<div class="seat-label"><b>${p.position}</b><small>${bb(p.stack)} BB</small></div>${p.seat===v.dealer?'<span class="dealer">D</span>':''}<div class="fold-text">${safe(p.name)}${p.folded?' · FOLD':p.allIn?' · ALL-IN':''}</div>${['award','refund'].includes(h.event.type)&&h.event.seat===p.seat?`<span class="stack-change">+${amount(h.event.amount)}</span>`:''}</div>`).join('');
 const wagers=v.players.map(p=>p.wager?`<span class="cash-wager wager-${p.seat}"><i class="chip mint"></i>${bb(p.wager)} BB</span>`:'').join('');
 const hero=v.players[0],active=h.phase==='betting'&&h.actor===0;
 return `<div class="page-top"><div><div class="eyebrow">Mesa contínua · ${t().config.rule==='button'?'sua regra do dealer':'blinds tradicionais'}</div><h1>Jogue. Reveja. Evolua.</h1><p>Decisões melhores começam com uma leitura honesta do seu jogo.</p></div>${a('new','↻ Nova mesa')}</div>${bankroll()}<div class="main-grid cash-grid"><section class="table-panel cash-table" aria-label="Mesa cash game"><div class="table-top"><div class="table-caption"><span class="status-dot"></span><strong>${h.kind==='omaha'?'Omaha 4 · PLO':'Hold’em · 6-max'}</strong><span>Mão ${h.number}</span></div><span class="street-badge">${h.phase==='finished'?'Encerrada':E.STREETS[h.street]}</span></div><div class="atmosphere-strip">${a('settings',`${atmosphere.icon} ${atmosphere.name} ⌄`,'text-button')}<span class="live-pressure">${t().config.rule==='button'?'Dealer paga 1 BB':'SB 0,5 · BB 1'}</span></div><div class="poker-stage cash-stage ${h.kind==='omaha'?'cash-omaha':''} ${hero.folded?'hero-folded':''}"><div class="felt"><div class="felt-pattern"></div><div class="table-watermark"><span>♠</span>MESA 10<small>CASH LAB</small></div></div>${seats}${wagers}<div class="board-area"><div class="pot"><span class="chip mint"></span><div><small>NO CENTRO</small><span class="pot-value">${bb(v.centerPot)} <span class="pot-unit">BB</span></span></div></div><div class="cash-board cards">${v.board.map((c,i)=>cards([c],'mini').replace('<div class="cards">',`<div class="${animate&&h.event.type==='reveal'&&i===v.board.length-1?'reveal-card':''}">`)).join('')}${Array.from({length:5-v.board.length},()=>'<span class="ghost-card"><i>♠</i></span>').join('')}</div><div class="board-caption">${h.kind==='omaha'?'2 da mão + 3 da mesa':'TOTAL COM APOSTAS: '+bb(v.pot)+' BB'}</div></div><div class="hero ${active?'hero-active':''}"><div class="hero-topline">${active?'Sua vez':hero.folded?'Você desistiu':'Você · '+hero.position}</div><div class="${animate&&h.event.type==='deal'&&h.event.seat===0?'new-hole-card':''}">${hero.cards.length?cards(hero.cards):'<div class="empty-hole">♠</div>'}</div><div class="hero-label"><span class="hero-indicator"></span><b>VOCÊ · ${hero.position}</b><span>${bb(hero.stack)} BB</span></div>${v.dealer===0?'<span class="dealer">D</span>':''}${['award','refund'].includes(h.event.type)&&h.event.seat===0?`<span class="stack-change">+${amount(h.event.amount)} BB</span>`:''}</div>${flight(h.event,animate)}</div><div class="cash-table-status" role="status">${safe(eventText(h.event))}</div><div class="table-bottom"><div class="street-track">${E.STREETS.map((s,i)=>`<span class="${i===h.street?'current':''}">${s}</span>`).join('')}</div><label class="speed-label">Animação <select id="cash-speed" aria-label="Velocidade das animações">${[['slow','Lenta'],['normal','Normal'],['fast','Rápida'],['off','Sem animação']].map(([k,l])=>`<option value="${k}" ${state.prefs.cashSpeed===k?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="hand-radar"><div class="radar-heading"><span class="eyebrow">Rastro da mão</span><span>Ações observadas</span></div><ol class="action-trail">${h.events.filter(e=>!['deal','reveal','button','finished','collect'].includes(e.type)).slice(-5).map(e=>`<li><span class="event-dot"></span><span><small>${E.STREETS[e.street]}</small>${safe(eventText(e))}</span></li>`).join('')}</ol></div></section><aside class="side-stack">${calibration()}${controls()}${opponentHUD()}<div class="note-card"><h3>${t().config.rule==='button'?'Ante do botão · regra própria':'Cash com blinds'}</h3><p>${t().config.rule==='button'?'Somente o dealer paga 1 BB obrigatório por mão. Esse ante não conta como uma aposta paga na rodada. A ação começa à esquerda do botão.':'Small blind paga 0,5 BB e big blind paga 1 BB. O botão gira após cada mão.'} As fichas seguem o resultado; erros não geram multas.</p></div></aside></div>`;}
 function opponentHUD(){const rows=D.opponents(t(),current().kind);return `<section class="opponent-hud"><span class="eyebrow">Pulso da mesa · ${current().kind==='omaha'?'Omaha':'Hold’em'} · pós-flop</span>${rows.map(p=>`<div class="pulse-row"><b>${safe(p.name)}</b><span class="meter"><span style="width:${Math.round((p.frequency||0)*100)}%"></span></span><small>${pct(p.frequency)} <em>em ${p.sample}</em></small></div>`).join('')}<p>Apostas ÷ (apostas + checks). Amostras pequenas não definem um estilo.</p></section>`;}
 function review(h=t().hand){const rows=h.decisions||[];openModal('Revisão da mão '+h.number,`<p>Compare o raciocínio com a referência didática. Ganhar ou perder não determina o acerto.</p>${rows.length?rows.map((d,i)=>`<section class="decision-review"><span class="eyebrow">${E.STREETS[d.context.street]} · decisão ${i+1}${d.assisted?' · com ajuda':''}</span><h3>${d.correct?'✓ Dentro da referência':'↗ Ponto para estudar'}</h3>${cards(d.context.cards,'small')}<p>Sua escolha: <strong>${labels[d.action]}</strong>${d.to?' para '+bb(d.to)+' BB':''}. Referência: ${labels[d.expected]}.</p><p>${safe(d.reason)}</p><small>Naquele momento: pote ${bb(d.context.pot)} BB · call ${bb(d.context.toCall)} BB.</small></section>`).join(''):'<p>A mão terminou sem uma decisão sua. Ela conta como experiência de mesa, mas não como evidência de estratégia.</p>'}`);}
 function graph(){const data=[C.bb(t().initialBankroll),...t().history.map(h=>h.bankroll)],min=Math.min(...data)-5,max=Math.max(...data)+5,points=data.map((v,i)=>`${10+i/Math.max(1,data.length-1)*620},${130-(v-min)/(max-min)*110}`).join(' ');return `<figure class="bank-graph"><figcaption>Banca simulada ao longo das mãos <span>${bb(data.at(-1))} BB</span></figcaption><svg viewBox="0 0 640 150" role="img" aria-label="Banca inicial ${data[0]} BB, atual ${data.at(-1)} BB, em ${data.length-1} mãos"><path d="M10 130H630" stroke="#456546"/><polyline points="${points}" fill="none" stroke="#b4e8a8" stroke-width="3" stroke-linejoin="round"/><circle cx="630" cy="${130-(data.at(-1)-min)/(max-min)*110}" r="4" fill="#e7c584"/></svg><p>Resultado observado em fichas fictícias; não é projeção de renda.</p></figure>`;}
 function report(){if(ai.note&&ai.hands!==t().history.length)ai={status:'idle'};const r=D.summarize(t()),om=D.summarize(t(),'omaha'),metrics=[['Mãos Hold’em',r.hands],['Decisões sem ajuda',r.unassisted],['Dentro da referência',pct(r.accuracy)],['Mãos Omaha',om.hands]];return `<div class="page-top"><div><div class="eyebrow">Seu jogo em revisão</div><h1>${r.calibrated?'Sua leitura inicial está aqui.':'Vamos conhecer seu jogo.'}</h1><p>${r.confidence}. ${r.calibrated?'O diagnóstico continua evoluindo.':'Complete dez mãos para abrir as prioridades de treino.'}</p></div>${a('back','← Voltar à mesa')}</div>${bankroll()}<div class="stat-grid">${metrics.map(([k,v])=>`<div class="stat-box"><strong>${v}</strong><span>${k}</span></div>`).join('')}</div>${graph()}${r.calibrated?`<div class="cash-priorities">${(r.priorities.length?r.priorities.slice(0,3):r.groups.slice(0,2)).map((g,i)=>`<article class="content-panel"><span class="eyebrow">${g.misses?'Prioridade '+(i+1):'Continuar observando'}</span><h2>${g.title}</h2><p>${g.opportunities?`${g.misses} desvio(s) em ${g.opportunities} decisão(ões) sem ajuda.`:'Ainda faltam oportunidades para avaliar este ponto.'}</p><p>${g.tip}</p>${g.evidence.map(e=>`<div class="evidence">Mão ${e.hand} · ${E.STREETS[e.street]} · ${e.position}: você escolheu ${labels[e.action].toLowerCase()}; a referência sugeria ${labels[e.expected].toLowerCase()}.</div>`).join('')}<p class="training-goal"><strong>Próxima meta:</strong> ${g.goal}</p>${g.examples.length?a('study','Praticar minhas decisões →','next-button',`data-key="${g.key}"`):a('back','Criar mais observações →','outline-btn')}</article>`).join('')}</div>`:`<div class="content-panel"><h2>${r.calibrationHands}/10 mãos observadas</h2><p>Ainda não há base para um diagnóstico. A calibração registra decisões; não treina um novo modelo de IA nem promete identificar seu estilo em dez mãos.</p>${a('back','Continuar calibração →','next-button')}</div>`}<div class="coach-layout cash-analysis"><section class="content-panel"><span class="eyebrow">Comportamentos observados · Hold’em</span><h2>Frequências com contexto.</h2><div class="metric-row"><span>Entrou voluntariamente (VPIP)</span><strong>${r.preflopHands?pct(r.vpip/r.preflopHands):'—'} <small>${r.vpip}/${r.preflopHands}</small></strong></div><div class="metric-row"><span>Aumentou pré-flop (PFR)</span><strong>${r.preflopHands?pct(r.pfr/r.preflopHands):'—'} <small>${r.pfr}/${r.preflopHands}</small></strong></div><div class="metric-row"><span>Apostas / ações pós-flop</span><strong>${r.postflopActions?pct(r.aggression/r.postflopActions):'—'}</strong></div><p>Antes e blinds obrigatórios não entram no VPIP. Esta amostra não mede seu desempenho em mesas reais. As comparações usam heurísticas e equidade contra mãos aleatórias, sem rake e sem estimar a faixa que pagaria.</p><p><strong>Omaha separado:</strong> ${om.unassisted} decisões sem ajuda; ${pct(om.accuracy)} dentro da referência. Use exatamente 2 cartas próprias e 3 da mesa.</p><p><strong>Banca:</strong> buy-in de 100 BB retirado de uma reserva simulada. ${t().rebuyCount} reentrada(s). Uma reentrada transfere fichas; não apaga perdas.</p></section><section class="content-panel"><span class="eyebrow">Segunda leitura opcional</span><h2>Revisão com Gemini.</h2><p>Envie apenas contagens e decisões resumidas da simulação. Não são enviadas cartas ocultas, saldo real ou dados de outros aplicativos.</p>${ai.note?Object.entries({summary:'Leitura inicial',opponentRead:'Leitura dos adversários',adjustment:'Ajuste para estudar',exercise:'Exercício',caveat:'Limites'}).map(([k,l])=>`<div class="ai-response"><h3>${l}</h3><p>${safe(ai.note[k])}</p></div>`).join(''):''}${ai.error?`<p role="status" class="method-note">${safe(ai.error)}</p>`:''}${a('ai',ai.status==='loading'?'Consultando…':'Analisar meu diagnóstico com Gemini','next-button',!r.calibrated||ai.status==='loading'?'disabled':'')}${a('publish','Como conectar no Netlify ↗','text-button')}<p class="privacy-note">A consulta é enviada ao Google somente ao clicar. O Free Tier tem cotas e pode usar o conteúdo para melhorar produtos. O coach local funciona sem chave. Não há garantia de lucro.</p></section></div>`;}
 function history(){return `<div class="page-top"><div><div class="eyebrow">Evolução da mesa</div><h1>O resultado conta uma parte.</h1><p>Reveja as decisões e acompanhe o saldo acumulado.</p></div>${a('back','← Mesa')}</div>${bankroll()}${graph()}<div class="history-list">${[...t().history].reverse().map(h=>`<article class="history-row"><div><strong>Mão ${h.number} · ${h.kind==='omaha'?'Omaha 4':h.position+' · Hold’em'}</strong><small>${h.decisions.length} decisão(ões) · saldo após a mão: ${bb(h.stack)} BB</small></div><b class="${h.delta<0?'negative':'positive'}">${h.delta>0?'+':''}${bb(h.delta)} BB</b>${a('review','Revisar →','outline-btn',`data-number="${h.number}"`)}</article>`).join('')||'<div class="content-panel"><p>Conclua sua primeira mão para iniciar o histórico.</p></div>'}</div>${state.cashArchives.length?`<section class="content-panel archived-tables"><h2>Mesas anteriores preservadas</h2>${state.cashArchives.map((x,i)=>`<p>Mesa ${i+1}: ${x.history.length} mãos · banca final ${amount(x.reserve+x.players[0].stack)} BB.</p>`).join('')}</section>`:''}${a('legacy','Ver histórico dos exercícios anteriores','text-button')}`;}
 function settings(){openModal('Configurar o treino cash',`<p>A cobrança no dealer é o padrão desta mesa. A regra e o clima escolhidos entram ao iniciar uma nova mesa.</p><h3 class="setting-section-title">Cobrança obrigatória</h3><label class="setting-option"><input type="radio" name="cash-rule" value="button" ${t().config.rule==='button'?'checked':''}><span><strong>Ante do botão · só o dealer paga</strong><small>1 BB de referência por mão, pago pelo botão. Sem SB/BB obrigatórios. Regra personalizada, não cash tradicional.</small></span></label><label class="setting-option"><input type="radio" name="cash-rule" value="blinds" ${t().config.rule==='blinds'?'checked':''}><span><strong>Cash tradicional</strong><small>Small blind de 0,5 BB e big blind de 1 BB. Para praticar esse formato.</small></span></label><h3 class="setting-section-title">Ritmo dos adversários</h3>${Object.entries(E.ATMOSPHERES).map(([k,m])=>`<label class="setting-option"><input type="radio" name="cash-mood" value="${k}" ${t().config.atmosphere===k?'checked':''}><span><strong>${m.name}</strong><small>${m.description}</small></span></label>`).join('')}<p class="modal-note">A mesa atual e seu histórico serão preservados ao abrir outra. A nova mesa começa uma nova banca simulada e calibração.</p>${a('save-settings','Salvar para a próxima mesa ✓','next-button')}${a('classic','Abrir exercícios independentes da versão anterior','text-button')}`);}
 function study(){const d=studyRows[studyIndex];openModal('Treino direcionado · '+(studyIndex+1)+'/'+studyRows.length,`<span class="eyebrow">Revisão da sua mão ${d.hand} · ${E.STREETS[d.context.street]}</span><p>Refaça esta decisão com o contexto que estava disponível naquele momento. Este exercício não movimenta sua banca e não entra na calibração.</p><div class="study-cards">${cards(d.context.cards,'small')}${d.context.board.length?cards(d.context.board,'small'):''}</div><p>${d.context.position} · pote ${bb(d.context.pot)} BB · para pagar ${bb(d.context.toCall)} BB.</p>${studyAnswer===null?`<div class="actions">${['fold',d.context.toCall?'call':'check',...(d.context.canRaise?['raise']:[])].map(k=>a('study-answer',labels[k],'action',`data-value="${k}"`)).join('')}</div>`:`<div class="method-note"><strong>${d.accepted.includes(studyAnswer)?'✓ Dentro da referência':'↗ Reveja este ponto'}</strong><p>${safe(d.reason)}</p><p>Meta: ${safe(D.THEMES[d.theme].goal)}</p></div>${a('study-next',studyIndex+1<studyRows.length?'Próximo exercício →':'Concluir revisão ✓','next-button')}`}`);}
 async function askAI(){if(ai.status==='loading'||t().history.length<10)return;const id=t().id,analyzedHands=t().history.length;ai={status:'loading'};render();try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),21000);let res;try{res=await fetch('/api/calibration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(D.payload(t())),signal:controller.signal});}finally{clearTimeout(timeout);}const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.code==='quota_exceeded'?'A cota da API foi atingida. O diagnóstico local continua disponível.':body.code==='not_configured'||[404,405,501].includes(res.status)?'A IA precisa da chave no Netlify. Abra “Como conectar”.':'A análise não foi recebida. Confira a chave, o modelo e os logs da função no Netlify.');if(!body.analysis?.summary)throw new Error('Resposta de IA inválida.');if(id===t().id)ai={status:'done',note:body.analysis,hands:analyzedHands};}catch(e){if(id===t().id)ai={status:'error',error:e.name==='AbortError'?'A API demorou demais. Seu progresso está salvo.':e.message};}render();}
 function handle(action,button){if(!action.startsWith('cash-'))return false;const type=action.slice(5),h=current();
 if(type==='play'){if(h.phase!=='betting'||h.actor!==0)return true;const value=button.dataset.value;let target;if(value==='raise'){const input=document.getElementById('cash-raise'),n=Number(input.value);if(!Number.isFinite(n)||!input.checkValidity()){input.reportValidity();return true;}target=C.money(n);}try{C.act(t(),value,target);}catch(e){toast(e.message);}save();render();}
 else if(type==='size'){const l=C.legal(t(),0);if(!l)return true;const f=button.dataset.fraction;document.getElementById('cash-raise').value=C.bb(f==='all'?l.maxTo:Math.min(l.maxTo,Math.max(l.minTo,l.already+l.call+Math.round((C.pot(t())+l.call)*Number(f)))));}
 else if(type==='skip'){C.runToHero(t());save();render();}
 else if(type==='pause'){paused=!paused;render();}
 else if(type==='next'){if(t().history.length===10&&t().reportSeen<10){t().reportSeen=10;host.nav('coach');}else{C.start(t());paused=false;save();render();}}
 else if(type==='back'){if(h.phase==='finished'&&t().history.length===10&&t().reportSeen===10&&t().players[0].stack>=100)C.start(t());host.nav('train');}
 else if(type==='report')host.nav('coach');
 else if(type==='history')host.nav('history');
 else if(type==='publish')host.nav('publish');
 else if(type==='review')review(button.dataset.number?t().history.find(x=>x.number===Number(button.dataset.number)):h);
 else if(type==='settings')settings();
 else if(type==='save-settings'){state.prefs.cashConfig={rule:document.querySelector('input[name="cash-rule"]:checked').value,atmosphere:document.querySelector('input[name="cash-mood"]:checked').value};save();document.getElementById('modal').close();toast('Configuração salva. Use Nova mesa para aplicar.');render();}
 else if(type==='new')openModal('Abrir outra mesa?',`<p>A mesa atual será arquivada com o saldo e o histórico. A nova começa com 100 BB na mesa e 900 BB de reserva simulada. ${h.phase!=='finished'?'A mão em andamento será guardada como incompleta.':''}</p>${a('new-confirm','Arquivar e abrir nova mesa','next-button')}`);
 else if(type==='new-confirm'){state.cashArchives.push(t());state.cash=C.make(state.prefs.cashConfig||t().config);ai={status:'idle'};document.getElementById('modal').close();paused=false;host.nav('train');}
 else if(type==='rebuy'){if(C.rebuy(t())){C.start(t());save();render();}}
 else if(type==='hint'){if(h.actor!==0||h.phase!=='betting')return true;h.assisted=true;const s=C.publicSpot(t()),ref=C.reference(s);save();openModal('Referência didática',`<p><strong>${labels[ref.expected]}</strong></p><p>${safe(ref.reason)}</p><p class="modal-note">Esta decisão foi marcada como assistida. A recomendação não é uma solução GTO.</p>`);}
 else if(type==='study'){studyRows=D.study(t(),button.dataset.key);studyIndex=0;studyAnswer=null;studyScore=0;if(studyRows.length)study();}
 else if(type==='study-answer'){if(studyAnswer!==null)return true;studyAnswer=button.dataset.value;if(studyRows[studyIndex].accepted.includes(studyAnswer))studyScore++;study();}
 else if(type==='study-next'){if(++studyIndex<studyRows.length){studyAnswer=null;study();}else openModal('Revisão concluída',`<p>${studyScore} de ${studyRows.length} respostas dentro da referência. Na próxima mão de cash, aplique a meta do exercício antes de decidir.</p>${a('study-close','Voltar ao diagnóstico','next-button')}`);}
 else if(type==='study-close'){document.getElementById('modal').close();host.nav('coach');}
 else if(type==='ai')askAI();
 else if(type==='classic'){document.getElementById('modal').close();host.nav('classic');}
 else if(type==='legacy')host.nav('legacy-history');
 return true;
 }
 document.addEventListener('change',e=>{if(e.target.id==='cash-speed'){state.prefs.cashSpeed=e.target.value;save();render();}});
 return {table,report,history,settings,schedule,handle,review,publish:()=>root.MesaPublishPage?.()||'',pause:()=>{paused=true;clearTimeout(timer);}};
};
})(window);
